script:
# GET → Meta verification
if frappe.request.method == "GET":
    frappe.response["message"] = frappe.request.args.get("hub.challenge")

# POST → Lead creation
elif frappe.request.method == "POST":

    data = frappe.request.get_json()

    platform = data.get("platform") or "Unknown"
    sender = data.get("sender") or "Guest"
    message = data.get("message") or "No message"

    # Map platform to Lead Source
    source_map = {
        "Instagram": "Social Media",
        "Facebook": "Social Media",
        "LinkedIn": "Social Media"
    }

    source = source_map.get(platform, "Other")

    # Check existing lead
    existing = frappe.db.exists("Lead", {"sender_id": sender})

    if existing:
        lead = frappe.get_doc("Lead", existing)
    else:
        lead = frappe.get_doc({
            "doctype": "Lead",
            "lead_name": sender,
            "first_name": sender,
            "source": source,
            "platform": platform,
            "sender_id": sender,
            "raw_message": str(data)
        })
        lead.insert(ignore_permissions=True)

    # Create readable message content
    content = f"""
Platform: {platform}
Sender: {sender}

Message:
{message}
"""

    frappe.get_doc({
        "doctype": "Communication",
        "communication_type": "Communication",
        "reference_doctype": "Lead",
        "reference_name": lead.name,
        "content": content
    }).insert(ignore_permissions=True)

    frappe.response["message"] = {
        "status": "success",
        "lead": lead.name
    }

def daily_lead_followup_reminder_cron():
    current_date = frappe.utils.today()
    leads = frappe.get_all(
        "CRM Lead",
        filters={"custom_follow_up_date": current_date},
        fields=["name"]
    )
    if not leads:
        return
    notification = frappe.get_doc("Notification", "Lead Follow-up Reminder")
    for lead in leads:
        doc = frappe.get_doc("CRM Lead", lead.name)
        notification.send(doc)

wfh_days = frappe.db.count(
    "Attendance",
    {
        "employee": doc.employee,
        "status": "Work From Home",
        "custom_wfh_type": "WFH employee",
        "attendance_date": [
            "between",
            [doc.start_date, doc.end_date]
        ]
    }
)

doc.custom_wfh_days = wfh_days

basic_amount = 0

for row in doc.earnings:

    if row.salary_component == "basic":
        basic_amount = row.amount

wfh_amount = (
    basic_amount
    * wfh_days
    * 0.4
) / (doc.payment_days or 1)

found = False

for row in doc.deductions:

    if row.salary_component == "WFH deduction":
        row.amount = wfh_amount
        found = True

if not found and wfh_amount > 0:

    doc.append("deductions", {
        "salary_component": "WFH deduction",
        "amount": wfh_amount
    })

if doc.lead and not doc.custom_service_interested:
    lead = frappe.get_doc("CRM Lead", doc.lead)
    doc.custom_service_interested = lead.custom_service_interested or ""

project_folder_name = None

# File attached directly to Project
if doc.attached_to_doctype == "Project":

    project_folder_name = frappe.db.get_value(
        "Project",
        doc.attached_to_name,
        "project_name"
    )

# File attached to Task
elif doc.attached_to_doctype == "Task":

    project = frappe.db.get_value(
        "Task",
        doc.attached_to_name,
        "project"
    )

    if project:
        project_folder_name = frappe.db.get_value(
            "Project",
            project,
            "project_name"
        )

if project_folder_name:

    # Find Projects root folder
    projects_root = frappe.db.get_value(
        "File",
        {
            "file_name": "Projects",
            "is_folder": 1
        },
        "name"
    )

    if projects_root:

        # Find matching folder
        project_folder = frappe.db.get_value(
            "File",
            {
                "file_name": project_folder_name,
                "is_folder": 1,
                "folder": projects_root
            },
            "name"
        )

        # Move file into project folder
        if project_folder and doc.folder != project_folder:
            doc.db_set("folder", project_folder)

for row in (doc.products or []):
    if row.custom_item and not row.product_name:
        item_name = frappe.db.get_value(
            "Item",
            row.custom_item,
            "item_name"
        )
        if item_name:
            row.product_name = item_name

if not doc.employee or not doc.start_date or not doc.end_date:
    pass
else:
    payment_days = doc.payment_days or 0
    if payment_days == 0:
        doc.custom_insufficient_hours = 0
        doc.custom_overtime_hours = 0
    else:
        checkins = frappe.get_all(
            "Employee Checkin",
            filters={
                "employee": doc.employee,
                "time": ["between", [doc.start_date, doc.end_date + " 23:59:59"]],
            },
            fields=["time", "log_type"],
            order_by="time asc"
        )
        daily_hours = {}
        i = 0
        while i < len(checkins) - 1:
            if checkins[i]["log_type"] == "IN" and checkins[i + 1]["log_type"] == "OUT":
                hours = frappe.utils.time_diff_in_hours(
                    checkins[i + 1]["time"],
                    checkins[i]["time"]
                )
                day = str(checkins[i]["time"])[:10]
                daily_hours[day] = daily_hours.get(day, 0) + hours
                i += 2
            else:
                i += 1

        total_insufficient = 0.0
        total_overtime = 0.0

        for day, worked in daily_hours.items():
            if worked < 8:
                total_insufficient += (8 - worked)
            elif worked > 8:
                total_overtime += (worked - 8)

        doc.custom_insufficient_hours = total_insufficient
        doc.custom_overtime_hours = total_overtime

        base = doc.base or 0
        if payment_days > 0:
            hourly_rate = base / payment_days / 8

            if total_insufficient > 0:
                deduction_amount = total_insufficient * hourly_rate
                for row in doc.deductions:
                    if row.salary_component == "Insufficient Hour Deduction":
                        row.amount = deduction_amount

            if total_overtime > 0:
                overtime_amount = total_overtime * hourly_rate
                for row in doc.earnings:
                    if row.salary_component == "OT Allowance":
                        row.amount = overtime_amount

today = frappe.utils.getdate(frappe.utils.nowdate())

# Only run if from_date exists
if doc.from_date:

    from_date = frappe.utils.getdate(doc.from_date)

    # ❗ Prevent past leave
    if from_date < today:
        frappe.throw("Leave cannot be applied for past dates")


    # ==============================
    # 1. Casual Leave → 2 days before
    # ==============================
    if doc.leave_type == "Casual Leave":
        diff = (from_date - today).days

        if diff < 2:
            frappe.throw("Casual Leave must be applied at least 2 days in advance")


    # ==============================
    # 2. Maternity Leave → 15 days before
    # ==============================
    elif doc.leave_type == "Maternity Leave":
        diff = (from_date - today).days

        if diff < 15:
            frappe.throw("Maternity Leave must be applied at least 15 days in advance")


    # ==============================
    # 3. Compensatory Off → within 7 days
    # ==============================
    elif doc.leave_type == "Compensatory Off":

        if not doc.work_from_date:
            frappe.throw("Work From Date is required for Compensatory Off")

        work_date = frappe.utils.getdate(doc.work_from_date)
        diff = (from_date - work_date).days

        if diff > 7:
            frappe.throw("Compensatory Off must be used within 7 days of the worked date")

        if diff < 0:
            frappe.throw("Leave date cannot be before the worked date")

if doc.lead:

    lead = frappe.get_doc("CRM Lead", doc.lead)

    if lead.email:

        existing_contact = frappe.db.exists(
            "Contact",
            {"email_id": lead.email}
        )

        if existing_contact:
            frappe.msgprint(
                f"Contact already exists: {existing_contact}"
            )

if doc.custom_url:
    source = frappe.get_all(
        "CRM Lead Source",
        filters={"custom_url": doc.custom_url},
        fields=["name"],
        limit=1
    )
    if source:
        doc.source = source[0]["name"]

# Ignore Lost Reason validation
# unless status is Lost

if doc.status != "Lost":

    # Force clear value
    doc.lost_reason = None

    # Remove mandatory validation
    doc.flags.ignore_mandatory = True

else:

    if not doc.lost_reason:

        frappe.throw(
            "Please select Lost Reason when status is Lost"
        )

total_hours = 0

attendance_list = frappe.get_all("Attendance",
    filters={
        "employee": doc.employee,
        "attendance_date": ["between", [doc.start_date, doc.end_date]],
        "docstatus": 1
    },
    fields=["working_hours"]
)

# Sum working hours
for att in attendance_list:
    total_hours += att.working_hours or 0

expected_hours = (doc.payment_days or 0) * 8

missing_hours = expected_hours - total_hours

# Get Basic salary
base_salary = 0
for e in doc.earnings:
    if e.salary_component and e.salary_component.lower() == "basic":
        base_salary = e.amount or 0

# ✅ Only run deduction if attendance exists
if total_hours > 0 and missing_hours > 0 and base_salary > 0 and expected_hours > 0:

    hourly_rate = base_salary / expected_hours
    deduction = missing_hours * hourly_rate

    # cap deduction
    deduction = min(deduction, base_salary)

    for d in doc.deductions:
        if d.salary_component == "Short Hours Deduction":
            d.amount = deduction

# 1. Ensure status is always set
if not doc.status:
    doc.status = "Open"


# 2. Handle workflow transitions safely
if doc.workflow_state:
    if doc.workflow_state == "Pending":
        doc.status = "Open"

    elif doc.workflow_state == "Approved":
        doc.status = "Approved"

    elif doc.workflow_state == "Rejected":
        doc.status = "Rejected"


# 3. Auto assign Reporting Manager as Leave Approver (SAFE)
if doc.employee:
    try:
        employee = frappe.get_doc("Employee", doc.employee)

        if employee.reports_to:
            manager = frappe.get_doc("Employee", employee.reports_to)

            if manager.user_id:
                doc.leave_approver = manager.user_id

    except Exception:
        pass
